(()=>{if(customElements.get('t4t-journey'))return;customElements.define('t4t-journey',class extends HTMLElement{connectedCallback(){if(this.ready)return;this.ready=true;this.steps=[...this.querySelectorAll('[data-stage]')];this.buttons=[...this.querySelectorAll('[data-phase-select]')];this.visual=this.querySelector('.journey-visual');const labels=['Getting comfortable','Finding their footing','Moving steadily','Exploring their pace','Running with confidence'];this.select=(index)=>{this.visual.dataset.phase=String(index);this.querySelector('.journey-state').textContent=labels[index];this.querySelector('.journey-visual-bottom>span:last-child').textContent=`0${index+1} / 05`;this.buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));this.steps.forEach((s,i)=>s.classList.toggle('is-active',i===index));this.querySelectorAll('[data-chart-point]').forEach((p,i)=>p.classList.toggle('is-active',i===index));};this.select(0);this.buttons.forEach((b,i)=>b.addEventListener('click',()=>{this.manualUntil=Date.now()+1200;this.select(i);if(matchMedia('(min-width:601px)').matches)this.steps[i].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});}));this.querySelector('.motion-toggle').addEventListener('click',e=>{const paused=this.visual.classList.toggle('motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'Play animation':'Pause animation';});if('IntersectionObserver'in window){this.visible=new Map();this.observer=new IntersectionObserver(entries=>{entries.forEach(e=>this.visible.set(e.target,e.isIntersecting?e.intersectionRatio:0));if(Date.now()<(this.manualUntil||0))return;const best=[...this.visible].sort((a,b)=>b[1]-a[1])[0];if(best&&best[1]>0)this.select(Number(best[0].dataset.stage));},{rootMargin:'-15% 0px -25% 0px',threshold:[0,.25,.5,.75,1]});this.steps.forEach(s=>this.observer.observe(s));}}disconnectedCallback(){this.observer?.disconnect();this.ready=false;}});})();